namespace functioncalls.graph;

/**
 * Represents whether a vertex is an incoming vertex (the start or from) on an edge, 
 * an outgoing vertex (the end or to) on an edge, or if it is both.
 */
public class FcgDirection
{	public static readonly FcgDirection IN = new();
	public static readonly FcgDirection IN_AND_OUT = new();
	public static readonly FcgDirection OUT = new();


	public bool isSource() {
		return this == IN_AND_OUT;
	}

	public bool isIn() {
		return this == IN;
	}

	public bool isOut() {
		return this == OUT;
	}
}
